<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#1e40af">
<title>My Profile | Flexi Educational Consult</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css">
<style>
:root{--blue:#1e40af;--ink:#0f172a;--muted:#64748b;--line:#e2e8f0;--bg:#f1f5f9}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif;line-height:1.55}header{background:#fff;border-bottom:3px solid var(--blue);padding:15px 5%;display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-weight:800;color:var(--blue);font-size:1.05rem}.nav{display:flex;gap:9px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;border-radius:10px;padding:10px 14px;font:inherit;font-size:.86rem;font-weight:800;border:1px solid var(--line);background:#fff;color:var(--blue)}.btn.primary{background:var(--blue);color:#fff;border-color:var(--blue)}main{width:min(100% - 28px,920px);margin:28px auto 45px}.eyebrow{font-size:.75rem;letter-spacing:.12em;text-transform:uppercase;font-weight:800;color:var(--blue);margin:0 0 7px}h1{font-size:clamp(1.6rem,4vw,2.1rem);margin:0 0 6px}.subtitle{color:var(--muted);margin:0}.notice{display:none;border-radius:12px;padding:13px 15px;margin:16px 0;font-size:.9rem;overflow-wrap:anywhere}.notice.show{display:block}.notice.error{background:#fef2f2;border:1px solid #fecaca;color:#991b1b}.notice.info{background:#eff6ff;border:1px solid #bfdbfe;color:#1e40af}.banner{display:flex;align-items:center;gap:16px;background:var(--blue);color:#fff;padding:23px;border-radius:18px;margin:20px 0}.avatar{width:66px;height:66px;border-radius:50%;background:#fff;color:var(--blue);display:grid;place-items:center;font-size:1.5rem;overflow:hidden;flex-shrink:0}.avatar img{width:100%;height:100%;object-fit:cover}.banner h2{font-size:1.2rem;margin:0 0 4px;overflow-wrap:anywhere}.banner p{margin:0;color:#dbeafe;font-size:.88rem;overflow-wrap:anywhere}.section{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px;margin:16px 0;box-shadow:0 5px 18px #0f172a0a}.section h2{font-size:1.05rem;color:var(--blue);margin:0 0 16px;padding-bottom:11px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:9px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px 18px}.field{min-width:0}.label{display:block;font-size:.72rem;text-transform:uppercase;letter-spacing:.05em;font-weight:800;color:var(--muted);margin-bottom:4px}.value{font-size:.94rem;font-weight:600;white-space:pre-wrap;overflow-wrap:anywhere}.empty{color:#94a3b8;font-weight:500}.subject-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.subject-card{border:1px solid var(--line);border-radius:12px;padding:13px;background:#f8fafc}.subject-card h3{margin:0 0 7px;font-size:.9rem;color:var(--blue)}.subject-card p{margin:0;font-size:.88rem;overflow-wrap:anywhere}.footnote{color:var(--muted);font-size:.8rem;margin:17px 2px 0}footer{text-align:center;padding:22px;color:var(--muted);font-size:.78rem}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}.nav{width:100%}.nav .btn{flex:1}.grid{grid-template-columns:1fr}.banner{padding:18px}.section{padding:16px}}
</style>
</head>
<body>
<header><div class="brand"><i class="fa-solid fa-graduation-cap"></i> Flexi Educational Consult</div><nav class="nav" aria-label="Profile navigation"><a class="btn" href="student-dashboard.php"><i class="fa-solid fa-gauge-high"></i> Dashboard</a><a class="btn primary" href="login.php"><i class="fa-solid fa-right-from-bracket"></i> Login</a></nav></header>
<main>
<div><p class="eyebrow">Student Portal</p><h1>My Profile Details</h1><p class="subtitle">Review the personal, parent/guardian, department, subscription, and exam information you entered during registration.</p></div>
<div id="message" class="notice" role="status" aria-live="polite"></div>
<section class="banner"><div class="avatar" id="avatar"><i class="fa-solid fa-user"></i></div><div><h2 id="fullName">Loading profile…</h2><p id="emailSummary">Retrieving your registration details</p><p id="registrationSummary"></p></div></section>
<section class="section"><h2><i class="fa-solid fa-user"></i> Student Personal Details</h2><div class="grid">
<div class="field"><span class="label">First name</span><div class="value" id="firstName">—</div></div><div class="field"><span class="label">Surname</span><div class="value" id="surname">—</div></div>
<div class="field"><span class="label">Date of birth</span><div class="value" id="dob">—</div></div><div class="field"><span class="label">Student phone / WhatsApp</span><div class="value" id="studentPhone">—</div></div>
<div class="field"><span class="label">Student email</span><div class="value" id="studentEmail">—</div></div><div class="field"><span class="label">Registration date</span><div class="value" id="registrationDate">—</div></div>
</div></section>
<section class="section"><h2><i class="fa-solid fa-users"></i> Parent / Guardian Contact Details</h2><div class="grid">
<div class="field"><span class="label">Parent phone number 1</span><div class="value" id="parentPhone1">—</div></div><div class="field"><span class="label">Parent phone number 2</span><div class="value" id="parentPhone2">—</div></div>
<div class="field"><span class="label">Parent email address 1</span><div class="value" id="parentEmail1">—</div></div><div class="field"><span class="label">Parent email address 2</span><div class="value" id="parentEmail2">—</div></div>
</div></section>
<section class="section"><h2><i class="fa-solid fa-graduation-cap"></i> Department &amp; Subscription</h2><div class="grid">
<div class="field"><span class="label">Department</span><div class="value" id="department">—</div></div><div class="field"><span class="label">Subscription package</span><div class="value" id="subscriptionLabel">—</div></div>
<div class="field"><span class="label">Subscription duration</span><div class="value" id="subscriptionMonths">—</div></div><div class="field"><span class="label">Package amount</span><div class="value" id="subscriptionAmount">—</div></div>
</div></section>
<section class="section"><h2><i class="fa-solid fa-book-open"></i> Examination Selection</h2><div class="field" style="margin-bottom:16px"><span class="label">Selected exam type(s)</span><div class="value" id="examTypes">—</div></div><div class="subject-grid" id="subjectsGrid"></div></section>
<p class="footnote">Profile details are displayed from the saved registration. A field marked “Not available” may not exist in an older registration record.</p>
</main><footer>© <span id="year"></span> Flexi Educational Consult</footer>
<script type="module">
import{initializeApp,getApps}from"https://www.gstatic.com/firebasejs/10.8.0/firebase-app.js";
import{getFirestore,doc,getDoc}from"https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
const config={apiKey:"AIzaSyCoGXb2XlvuwcJY8oyW6_J42fgxfH5vZao",authDomain:"jarvisai-1a594.firebaseapp.com",projectId:"jarvisai-1a594",storageBucket:"jarvisai-1a594.firebasestorage.app",messagingSenderId:"868499596875",appId:"1:868499596875:web:4bf592934f6086be8a4fce"};
const app=getApps().find(a=>a.name==="flexi-profile")||initializeApp(config,"flexi-profile"),db=getFirestore(app),$=id=>document.getElementById(id);$("year").textContent=new Date().getFullYear();
function display(id,value){const e=$(id),v=value===undefined||value===null||value===""?"Not available":String(value);e.textContent=v;if(v==="Not available")e.classList.add("empty")}
function dateText(value){if(!value)return"Not available";let d=value;if(typeof value==="object"&&typeof value.toDate==="function")d=value.toDate();else if(typeof value==="object"&&value.seconds)d=new Date(value.seconds*1000);else d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString("en-NG",{day:"numeric",month:"long",year:"numeric"})}
function money(value){const n=Number(value);return value===undefined||value===null||value===""||!Number.isFinite(n)?"Not available":"₦"+n.toLocaleString("en-NG")}
function render(d,id){const first=d.firstName||d.firstname||"",last=d.surname||d.lastName||d.lastname||"",name=[first,last].filter(Boolean).join(" ").trim()||d.studentName||"Student";$("fullName").textContent=name;$("emailSummary").textContent=d.studentEmail||d.email||"Email not available";$("registrationSummary").textContent="Registration ID: "+(d.registrationId||id||"Not available");const photo=d.profilePhotoBase64||d.photoBase64||d.profileImageBase64||"";if(/^data:image\/(png|jpeg|jpg|webp);base64,/i.test(photo)){const img=document.createElement("img");img.src=photo;img.alt="Student profile photo";$("avatar").replaceChildren(img)}
display("firstName",first);display("surname",last);display("dob",dateText(d.dob));display("studentPhone",d.studentPhone||d.whatsappNumber||d.whatsapp||d.phone);display("studentEmail",d.studentEmail||d.email);display("registrationDate",dateText(d.registrationDate||d.createdAt));display("parentPhone1",d.parentPhone1);display("parentPhone2",d.parentPhone2);display("parentEmail1",d.parentEmail1);display("parentEmail2",d.parentEmail2);display("department",d.department);display("subscriptionLabel",d.subscriptionLabel||d.subscriptionPlan);display("subscriptionMonths",d.subscriptionMonths?(d.subscriptionMonths+" "+(Number(d.subscriptionMonths)===1?"month":"months")):"");display("subscriptionAmount",money(d.subscriptionAmount||d.amountPaid));
const exams=Array.isArray(d.examTypes)?d.examTypes:(d.examType?[d.examType]:[]);display("examTypes",exams.length?exams.join(", "):"");const subjects=d.subjects&&typeof d.subjects==="object"?d.subjects:{},grid=$("subjectsGrid");grid.replaceChildren();let count=0;for(const key of ["JAMB","SSCE","JUPEB"]){const list=Array.isArray(subjects[key])?subjects[key]:[];if(!list.length)continue;count++;const card=document.createElement("div");card.className="subject-card";const h=document.createElement("h3");h.textContent=key+" subjects";const p=document.createElement("p");p.textContent=list.join(", ");card.append(h,p);grid.append(card)}if(!count){const card=document.createElement("div");card.className="subject-card";card.textContent="No examination subjects were found in this saved registration.";grid.append(card)}}
async function load(){const id=localStorage.getItem("flexiCurrentRegId");let local={};try{local=JSON.parse(localStorage.getItem("flexiStudentRegistration")||"{}")||{}}catch(e){}
if(id){try{const snap=await getDoc(doc(db,"registrations",id));if(snap.exists()){const remote=snap.data(),merged={...local,...remote};if((!remote.subjects||!Object.keys(remote.subjects).length)&&local.subjects)merged.subjects=local.subjects;if((!remote.examTypes||!remote.examTypes.length)&&local.examTypes)merged.examTypes=local.examTypes;render(merged,id);return}}catch(e){console.error(e)}}
if(Object.keys(local).length){render(local,id);$("message").textContent="Showing registration details saved in this browser. Sign in on this device to load the latest Firestore record.";$("message").className="notice show info";return}
$("fullName").textContent="Profile not loaded";$("emailSummary").textContent="No registration details available";$("registrationSummary").textContent="";$("message").textContent="No student registration was found. Please sign in first, then open Profile details from the dashboard.";$("message").className="notice show error"}
load();
</script>
</body>
</html>
